describe('Search Filter', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
    });

    it('should display results when items match the search', () => {
        cy.get('input[name="search"]').type('valid search term'); // Replace with an actual search term
        cy.get('button[type="submit"]').click();
        cy.get('.results').should('be.visible');
        cy.get('.results').should('not.contain', 'No results');
    });

    it('should display a "No results" message when no items match the search', () => {
        cy.get('input[name="search"]').type('invalid search term'); // Replace with a term that yields no results
        cy.get('button[type="submit"]').click();
        cy.get('.no-results-message').should('be.visible').and('contain', 'No results');
    });
});
